import base64,gzip,json,re,urllib.request,urllib.error
API='https://m3-nvocc-api-latest-1.onrender.com'
D=json.loads(gzip.decompress(base64.b64decode('')).decode())
src=open('app/admin_seed.py').read()
def cred(user):
    m=re.search(r"\('USR-[^']+','"+re.escape(user)+r"','[^']+','[^']+','([^']+)'",src)
    if not m: raise RuntimeError('credential seed not found: '+user)
    return m.group(1)
def call(path,payload=None,token=None):
    data=None if payload is None else json.dumps(payload,separators=(',',':')).encode()
    h={'Content-Type':'application/json'}
    if token:h['X-M3-Session']=token
    q=urllib.request.Request(API+path,data=data,headers=h,method='POST')
    try:
        with urllib.request.urlopen(q,timeout=60) as r:
            raw=r.read().decode(); return r.status,json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        raw=e.read().decode()
        try:o=json.loads(raw)
        except:o={'raw':raw}
        return e.code,o
def login(u):
    st,o=call('/api/admin/auth/login',{'username':u,'password':cred(u),'mfa_code':'123456'})
    if st!=200:raise RuntimeError((u,st,o))
    return o['session_token']
maker,checker=login('md.maker'),login('md.checker')
res={'common_party':{'submitted':0,'approved':0,'failed':[]},'agent':{'submitted':0,'approved':0,'failed':[]}}
for bucket,items in [('common_party',D['common_parties']),('agent',D['agents'])]:
    refs=[]
    for item in items:
        st,o=call('/api/masterdata/changes',item,maker)
        if st==200:res[bucket]['submitted']+=1;refs.append((item['record_key'],o['change_ref']))
        else:res[bucket]['failed'].append({'key':item['record_key'],'stage':'submit','status':st,'detail':o})
    for key,ref in refs:
        st,o=call('/api/masterdata/changes/'+ref+'/decision',{'decision':'APPROVE','comment':'Controlled approved real-data import'},checker)
        if st==200 and o.get('status')=='APPROVED':res[bucket]['approved']+=1
        else:res[bucket]['failed'].append({'key':key,'stage':'approve','status':st,'detail':o})
print('M3_REAL_PARTY_IMPORT_RESULT='+json.dumps(res,separators=(',',':'),sort_keys=True))
if res['common_party']['approved']!=45 or res['agent']['approved']!=48: raise SystemExit(2)
